#!/usr/bin/env bash
# Palomar LIX-strong surface verification (generated by rescue-lix; runs on MSI through dispatch.sh).
# Under the clone's lock: clone sources := origin/main@SHA export, overlay the local Palomar surface
# (lakefile.toml, Palomar/*, scripts/Palomar*, scripts/check_palomar_*), build the six Palomar libs,
# run the strengthened axioms driver, the statement-match script and the submission self-test.
# The clone's lakefile is restored to origin's at the end.
set -u
P=/projects/standard/__MSI_GROUP__/__MSI_USER__
export HOME=$P ELAN_HOME=$P/.elan XDG_CACHE_HOME=$P/.cache PATH=$P/.elan/bin:$PATH
CLONE=__CLONE__; TAG=__TAG__; SHA=__SHA__
NMR=$P/nm; PY=$P/params-venv/bin/python3
LOG=$CLONE/.nm/palomar-$TAG.log
export LEAN_NUM_THREADS=${NT:-16}
summary_fail() { echo "===== SUMMARY"; echo "$1"; exit "${2:-4}"; }
exec 9>"$CLONE/.lake/laneprobe.lock"
flock -w 14400 9 || summary_fail "PALOMAR VERIFY FAILED: clone lock not free after 4 h (infra)" 3
mkdir -p "$NMR/exports"; EXP=$NMR/exports/$SHA
if [ ! -e "$EXP/.done" ]; then
  exec 8>"$NMR/exports/.lock"; flock -w 1800 8
  if [ ! -e "$EXP/.done" ]; then
    git -C "$NMR/mirror.git" fetch -q origin 2>/dev/null
    git -C "$NMR/mirror.git" cat-file -e "$SHA^{commit}" || summary_fail "PALOMAR VERIFY FAILED: mirror lacks $SHA (infra)"
    rm -rf "$EXP.tmp"; mkdir -p "$EXP.tmp"
    git -C "$NMR/mirror.git" archive "$SHA" GroupApproximation GroupApproximation.lean scripts | tar -x -C "$EXP.tmp" || summary_fail "PALOMAR VERIFY FAILED: export (infra)"
    touch "$EXP.tmp/.done"; mv "$EXP.tmp" "$EXP"
  fi
  exec 8>&-
fi
rsync -rlc --delete "$EXP/GroupApproximation/" "$CLONE/GroupApproximation/" || summary_fail "PALOMAR VERIFY FAILED: source sync (infra)"
rsync -lc "$EXP/GroupApproximation.lean" "$CLONE/GroupApproximation.lean"
git -C "$NMR/mirror.git" show "$SHA:lakefile.toml" > "$CLONE/.nm/lakefile-origin-$TAG.toml"
OV=$CLONE/.nm/pal-$TAG
rsync -rlc --exclude __pycache__ "$EXP/scripts/" "$CLONE/scripts/"
mkdir -p "$CLONE/Palomar"
git -C "$NMR/mirror.git" archive "$SHA" Palomar | tar -x -C "$CLONE"
rsync -rlc "$OV/" "$CLONE/" || summary_fail "PALOMAR VERIFY FAILED: overlay apply (infra)"
cd "$CLONE" || summary_fail "PALOMAR VERIFY FAILED: no clone"
rm -rf scripts/__pycache__
python3 "$P/cc_clones/purge_stale.py" "$CLONE" > "$LOG" 2>&1
echo "[palomar] $(hostname -s) threads=$LEAN_NUM_THREADS base=$SHA" >> "$LOG"
RC_ALL=0
SUMF=$CLONE/.nm/palsteps-$TAG.txt; : > "$SUMF"
step() { local name=$1; shift; echo "=== STEP $name: $*" >> "$LOG"; timeout 7200 nice -n 5 "$@" >> "$LOG" 2>&1; local rc=$?; echo "=== STEP $name rc=$rc" >> "$LOG"; [ $rc -eq 0 ] || RC_ALL=1; echo "$name rc=$rc" >> "$SUMF"; }
for f in formalization.yaml LICENSE lean-toolchain lake-manifest.json; do git -C "$NMR/mirror.git" show "$SHA:$f" > "$CLONE/$f" 2>/dev/null; done
rm -f "$CLONE/COPYING"
step build lake build PalomarChallenge PalomarSolution PalomarLIXChallenge PalomarLIXSolution PalomarLIXStrongChallenge PalomarLIXStrongSolution
step axioms lake env lean scripts/PalomarLIXStrongAxioms.lean
step statement-match bash scripts/check_palomar_statement_match.sh
step submission-selftest "$PY" scripts/check_palomar_submission.py --self-test
step submission "$PY" scripts/check_palomar_submission.py
cp "$CLONE/.nm/lakefile-origin-$TAG.toml" "$CLONE/lakefile.toml"
echo "===== SUMMARY"
echo "host $(hostname -s) base ${SHA:0:9} log $LOG"
cat "$SUMF"
echo "--- errors (first 60 lines)"
grep -n -E '^error|error:|✖|FAIL|Traceback|mismatch|sorryAx' "$LOG" | head -60
if [ $RC_ALL -eq 0 ]; then echo "PALOMAR VERIFY GREEN"; else echo "PALOMAR VERIFY FAILED"; fi
exit $RC_ALL
